BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT jsonb_build_object('calls',(SELECT count(*) FROM lifecycle_storage_call),'observations',(SELECT count(*) FROM lifecycle_storage_observation),'physical_invocations',(SELECT count(*) FROM lifecycle_storage_observation WHERE invoked_at IS NOT NULL),'typed_native_costs',(SELECT count(*) FROM cost_allocation a JOIN cost_event e ON e.id=a.cost_event_id WHERE a.lifecycle_storage_call_id IS NOT NULL AND e.activity_id=a.lifecycle_storage_call_id AND e.quantity=1 AND e.unit='invocation'),'unaccounted',(SELECT count(*) FROM lifecycle_storage_observation o WHERE o.invoked_at IS NOT NULL AND (SELECT count(*) FROM cost_allocation a WHERE a.lifecycle_storage_call_id=o.call_id)<>1),'active_pins',(SELECT count(*) FROM lifecycle_reader_pin p WHERE NOT EXISTS(SELECT 1 FROM lifecycle_reader_termination t WHERE t.pin_id=p.id)),'send_claims',(SELECT count(*) FROM lifecycle_provider_send_claim),'absence',(SELECT count(*) FROM lifecycle_copy_absence_receipt),'completion',(SELECT count(*) FROM lifecycle_plan_completion),'delete_calls',(SELECT count(*) FROM lifecycle_provider_observation WHERE invoked_at IS NOT NULL),'recoveries',(SELECT count(*) FROM evidence WHERE evidence_type='EXECUTION_RECOVERY'),'estimated_engine_costs',(SELECT jsonb_agg(to_jsonb(e) ORDER BY id) FROM cost_event e WHERE cost_type='NATIVE_ENGINE_INVOCATION'));
ROLLBACK;
